$ = result;
for (i in $) {
    if (/vol_name/.test(String($[i]))) {
        text = "🏮 ↓ 〖" + String($[i].text()) + "〗 ↓ 🏮";
        list.push({
            text: text,
            volume: true
        });
    } else {  
        $[i].select("td").forEach(a => {     
